package com.technova.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="comprobante") public class Comprobante { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_comprobante") private Long id; @Column(name="id_pedido") private Long pedidoId; private String serie; private Integer numero; private String tipo; @Column(name="fecha_emision") private LocalDateTime fechaEmision; @Column(name="cliente_nombre") private String clienteNombre; private String documento; private BigDecimal subtotal,igv,total; public Comprobante(){} public Long getId(){return id;} public void setId(Long v){id=v;} public Long getPedidoId(){return pedidoId;} public void setPedidoId(Long v){pedidoId=v;} public String getSerie(){return serie;} public void setSerie(String v){serie=v;} public Integer getNumero(){return numero;} public void setNumero(Integer v){numero=v;} public String getTipo(){return tipo;} public void setTipo(String v){tipo=v;} public LocalDateTime getFechaEmision(){return fechaEmision;} public void setFechaEmision(LocalDateTime v){fechaEmision=v;} public String getClienteNombre(){return clienteNombre;} public void setClienteNombre(String v){clienteNombre=v;} public String getDocumento(){return documento;} public void setDocumento(String v){documento=v;} public BigDecimal getSubtotal(){return subtotal;} public void setSubtotal(BigDecimal v){subtotal=v;} public BigDecimal getIgv(){return igv;} public void setIgv(BigDecimal v){igv=v;} public BigDecimal getTotal(){return total;} public void setTotal(BigDecimal v){total=v;} }
